package com.asmj.marketplace.notification.service;import com.asmj.marketplace.notification.model.Notification;import com.asmj.marketplace.notification.repository.NotificationRepository;import com.asmj.marketplace.user.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.time.Instant;import java.util.*;@Service@RequiredArgsConstructor public class NotificationService{private final NotificationRepository repo;private final UserRepository users;public List<Notification> mine(String e){return repo.findByUserIdOrderByCreatedAtDesc(users.findByEmailIgnoreCase(e).orElseThrow().getId());}public Notification create(String uid,String title,String message,String type){return repo.save(Notification.builder().userId(uid).title(title).message(message).type(type).read(false).createdAt(Instant.now()).build());}public void read(String id){repo.findById(id).ifPresent(n->{n.setRead(true);repo.save(n);});}}
